// Pipeline Hazard Forwarding Logic (EX Stage Input)

#define REG_ZERO 0

// Pipeline Register Outputs (Rd, Write Enable)
int Dest_EXMEM, Dest_MEMWB;
bool Write_EXMEM, Write_MEMWB;

// Current Instruction Inputs (Rs1, Rs2)
int Rs1_IDEX, Rs2_IDEX;

// --- Operand A (Rs1) Forwarding Check ---

// Path 1: Forward from EX/MEM stage (Result is freshest)
if (Write_EXMEM && Dest_EXMEM != REG_ZERO && Dest_EXMEM == Rs1_IDEX)
    return EXMEM_ALU_Result;

// Path 2: Forward from MEM/WB stage (Requires stall check avoidance)
if (Write_MEMWB && Dest_MEMWB != REG_ZERO && Dest_MEMWB == Rs1_IDEX) {
    // If EX/MEM is not writing to Rs1, use MEM/WB result
    if (Dest_EXMEM != Rs1_IDEX)
        return MEMWB_Value;
}
